#!/usr/bin/env node
// Evidence packaging only. Every expected output below is generated by executing
// the released kernel; the production city never loads these expected outputs.
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {loadKernel,loadLibraries,execute} from '../runtime/system.mjs';
import {encodeImage,decodeImage,sha256} from '../dist/images.mjs';
const kernel=await loadKernel(),m=kernel.create();
if(kernel.programHash!=='0ebd529deaf21dd77bba0ddaef77693e27fd1fffbc9930c9ca31b0bbde400d98')throw new Error('Historical Build002 evidence tool: use the matching build-002 checkout. Current artifacts must not overwrite that record.');
function command(machine,source){execute(machine,source+'\n',{fuel:2e14,blocks:3e10});if(machine.state!=='input')throw new Error('Native operation incomplete');return new TextDecoder().decode(machine.drain());}
const boot=command(m,await loadLibraries('city-system.json'));
if(/!E\d+|WS-ERROR/.test(boot))throw new Error('Native boot failed');
const initialImage=await encodeImage(m,kernel.programHash),source=': delivery-rule.thread 8 * + ;';
const commonInputs=Array(3).fill('city-step city-state workspace-state'),runs=[];
for(const [label,setup] of [['Original',[]],['Toll-averse source',[`${source.length} 0 source-write ${source}\n0 module-compile`]]]) {
  const machine=await decodeImage(initialImage,{program:kernel.program,programHash:kernel.programHash,create:kernel.create});
  const inputs=[...setup,...commonInputs],expectedOutputs=inputs.map(input=>command(machine,input));
  runs.push({label,inputs,expectedOutputs});
}
const paths=['kernel.bf.gz','kernel-map.json','executor.wasm','engine.mjs','wasm-engine.mjs','worker.mjs','images.mjs','programs/core.thread','programs/city-state.thread','programs/workspace.thread','programs/city.thread','programs/city-boot.thread','programs/city-system.json'];
const artifactSha256=Object.fromEntries(await Promise.all(paths.map(async path=>[path,await sha256(await readFile(new URL('../dist/'+path,import.meta.url)))])));
const bundle={schema:'8i-replay-1',build:'002',kernelSha256:kernel.programHash,artifactSha256,initialImage,runs,sourceVariants:[{source,sha256:await sha256(source)}],instructions:'From the matching Build 002 checkout, run: node tools/replay.mjs dist/reproduction/build-002.json. Node.js 22+. All kernel, executor and Thread artifacts are checked against artifactSha256. Each branch starts in a fresh BF machine from the identical initial image. Source setup is the independent variable; the next three logical inputs are identical, including the open toll bridge. Expected outputs are evidence only, never a production calculation path.'};
await mkdir(new URL('../dist/reproduction/',import.meta.url),{recursive:true});
await writeFile(new URL('../dist/reproduction/build-002.json',import.meta.url),JSON.stringify(bundle,null,2)+'\n');
console.log(JSON.stringify({kernelSha256:kernel.programHash,branches:runs.length,initialImageBytes:initialImage.length,sourceSha256:await sha256(source)}));
